package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.access.AccessService;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.claim.Tags;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people on a sheet: listed by their position, a new person going to the end and a person moved up
 * or down swapping with their neighbour, added and edited one at a time;
 * an edit made from a version someone else has saved since is refused. A person can be retired from a
 * date; no claim dated after it can then be added for them. A retired person can be unretired; no claim
 * dated within a past retirement (after its from-date, before its to-date) can be added for them either. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;
    private final Tags tags;
    private final PersonSnapshotRepository snapshots;
    private final AccessService access;

    public PersonService(PersonRepository people, PatronRepository patrons, SheetService sheets,
            SheetRepository sheetRows, Rollup rollup, ApplicationEventPublisher events, Tags tags,
            PersonSnapshotRepository snapshots, AccessService access) {
        this.access = access;
        this.tags = tags;
        this.snapshots = snapshots;
        this.patrons = patrons;
        this.sheetRows = sheetRows;
        this.rollup = rollup;
        this.people = people;
        this.sheets = sheets;
        this.events = events;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
    }

    @Transactional(readOnly = true)
    public Person get(String sheetId, long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        return add(sheetId, user, name, grade, terms, contact, null);
    }

    /** Add the person, carrying the tags in the comma separated text (see {@link Tags#normalize}; null: none). */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact,
            String tagText) {
        return add(sheetId, user, name, grade, terms, null, contact, tagText);
    }

    /** Add the person as above, their own terms from the date (null: from the beginning of time). */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, LocalDate termsFrom,
            String contact, String tagText) {
        String tagged = Tags.normalize(tagText);
        sheets.load(sheetId, user);
        sheetRows.lockById(sheetId);
        String trimmed = name.trim();
        if (inUse(sheetId, trimmed, null)) {
            throw nameInUse();
        }
        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
            throw contactInUse();
        }
        Rollup.Figures before = rollup.figures(sheetId);
        Person added = new Person(sheetId, trimmed, grade);
        if (termsFrom != null) {
            if (terms != null) {
                added.termsFrom(terms, termsFrom);
            }
        } else {
            added.setTerms(terms);
        }
        added.setContact(contact);
        added.setTags(tagged);
        added.setPosition(people.maxPosition(sheetId) + 1);
        Person person = people.saveAndFlush(added);
        tags.use(sheetId, tagged);
        Integer termsNow = person.termsOn(sheets.today(sheetId));
        events.publishEvent(new PersonChanged("PERSON_ADDED", sheetId, user, trimmed, grade,
                termsNow == null ? null : termsNow.toString(), contact));
        rollup.changed(sheetId, user, before);
        return person;
    }

    /**
     * Save the person's name and record the grade from a date (none: the sheet's today), keeping the
     * grades already recorded; a grade left as the row showed it (in force on the sheet's today) with no
     * date records nothing. The person's own terms and contact are set to those given (null: none); a contact
     * another person on the sheet has is refused. The edit names the grade in force on the sheet's today after
     * it and, when they changed, the terms and the contact.
     */
    @Transactional
    public Person edit(String sheetId, String user, long personId, Long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        return edit(sheetId, user, personId, version, name, grade, gradeFrom, terms, contact, null);
    }

    /** Edit the person as above, their tags set to those in the comma separated text (see {@link Tags#normalize}; null: as they were). */
    @Transactional
    public Person edit(String sheetId, String user, long personId, Long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact, String tagText) {
        return edit(sheetId, user, personId, version, name, grade, gradeFrom, terms, null, contact, tagText);
    }

    /**
     * Edit the person as above, their own terms recorded from a date: with a from-date, the terms (null: none)
     * are recorded from it, keeping those already recorded (one from the same date is replaced); with none, the
     * terms are those from the beginning of time, unless they are the terms in force on the sheet's today (as the
     * row showed them), which records nothing. When the terms recorded changed, the edit names the terms in force
     * on the sheet's today after it.
