  const headers = { 'X-User': this.session.user() ?? '' };
  this.bulkGrading = true;
  try {
    const result = await firstValueFrom(
      this.http.post<{ graded: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/grade`,
        { personIds, grade, from: from || null },
        { headers },
      ),
